256	export function parseNatallyStream(raw: string, chart: NatalChartResult): NatallyChatResult {
257	  // '[' often arrives one token before the second '[' in a hidden command.
258	  if(raw.endsWith('[') && !raw.endsWith('[['))raw=raw.slice(0,-1);
259	  const cue = raw.lastIndexOf('[[');
260	  if (cue >= 0 && raw.indexOf(']]', cue) < 0) raw = raw.slice(0, cue);
261	  const metadata = raw.indexOf('---ASTROLOGICAL PROVENANCE---');
262	  if (metadata >= 0) raw = raw.slice(0, metadata);
263	  const trailing = raw.lastIndexOf('\n---');
264	  if (trailing >= 0 && '---ASTROLOGICAL PROVENANCE---'.startsWith(raw.slice(trailing + 1))) raw = raw.slice(0, trailing);
265	  return parseNatallyResponse(raw, chart);
266	}
